--
-- Esquema convertido de MySQL/MariaDB (phpMyAdmin) a PostgreSQL
-- Compatible con NeonDB
-- Base de datos original: u638824328_medi
--
-- Cambios realizados respecto del original:
--   * Se removieron los backticks (`) y se usaron comillas dobles ("") solo donde es necesario.
--   * tinyint(1) -> boolean (columna anonimo).
--   * int(N) -> integer.
--   * AUTO_INCREMENT -> GENERATED ALWAYS AS IDENTITY (equivalente a SERIAL) con el valor
--     inicial correspondiente (se preserva el próximo id a asignar).
--   * DEFAULT '0000-00-00' (fecha inválida en MySQL) -> se removió el default y los valores
--     de datos '0000-00-00' se convirtieron a NULL.
--   * Se agregó "ON DELETE" no aplica: no había foreign keys explícitas en el dump original.
--   * ENGINE/CHARSET/COLLATE de MySQL se removieron (no aplican en PostgreSQL; Neon usa UTF-8).
--

BEGIN;

-- --------------------------------------------------------
-- Tabla: comunicacion
-- --------------------------------------------------------

CREATE TABLE "comunicacion" (
    "id" integer NOT NULL,
    "caracter" varchar(100) NOT NULL,
    "titulo" varchar(300) NOT NULL,
    "descripcion" varchar(5000) NOT NULL,
    "ubicacion_1" varchar(500) NOT NULL,
    "ubicacion_2" varchar(200) NOT NULL,
    "destinacion" varchar(200) NOT NULL,
    "nombre" varchar(500) NOT NULL,
    "telefono" varchar(100) NOT NULL,
    "email" varchar(200) NOT NULL,
    "domicilio" varchar(500) NOT NULL,
    "anonimo" boolean NOT NULL,
    "fecha" date NOT NULL,
    "hora" time NOT NULL,
    "estado" varchar(100) NOT NULL,
    "plazo_resolucion" varchar(200) NOT NULL,
    "vencimientos" integer NOT NULL,
    "fecha_v" date NOT NULL,
    "file_1" varchar(300) DEFAULT NULL,
    "cod_conf" varchar(50) NOT NULL,
    "seguimiento" varchar(250) DEFAULT NULL,
    "comentario" varchar(1000) NOT NULL DEFAULT '--',
    "fecha_r" date DEFAULT NULL,
    "conforme" varchar(20) DEFAULT 'Aún sin valoración',
    "feedback" varchar(1000) DEFAULT 'Aún sin comentarios',
    "contador_dias" integer DEFAULT 0,
    "contador_dias_p" integer NOT NULL DEFAULT 0,
    CONSTRAINT "comunicacion_pkey" PRIMARY KEY ("id")
);

-- --------------------------------------------------------
-- Tabla: destinaciones
-- --------------------------------------------------------

CREATE TABLE "destinaciones" (
    "id" integer NOT NULL,
    "nombre_area" varchar(200) NOT NULL,
    "descripcion" varchar(300) NOT NULL,
    "pendientes" integer NOT NULL DEFAULT 0,
    "iniciados" integer NOT NULL DEFAULT 0,
    "demorados" integer NOT NULL DEFAULT 0,
    "resueltos" integer NOT NULL DEFAULT 0,
    "eliminados" integer NOT NULL DEFAULT 0,
    "clave_poder" varchar(200) NOT NULL,
    "email" varchar(200) NOT NULL,
    "color" integer DEFAULT 1,
    CONSTRAINT "destinaciones_pkey" PRIMARY KEY ("id")
);

-- --------------------------------------------------------
-- Tabla: usuario
-- --------------------------------------------------------

CREATE TABLE "usuario" (
    "id" integer NOT NULL,
    "user" varchar(18) NOT NULL,
    "pass" varchar(18) NOT NULL,
    "clave_poder" varchar(40) NOT NULL,
    "nombre" varchar(100) NOT NULL,
    "operador" varchar(200) DEFAULT NULL,
    "rol" varchar(300) NOT NULL,
    CONSTRAINT "usuario_pkey" PRIMARY KEY ("id")
);

-- --------------------------------------------------------
-- Datos
-- --------------------------------------------------------

