  (1263, 'Denuncia', 'NEGACION DE REINTEGRO DE DINERO', 'La señora Eufemia Usqueda se niega a reintegrarse mi.dinero que el día 10 de abril yo le pague como seña de alquiler de su cabaña en Tinogasta, a pesar de haberle transferido 30 mil pesos ella la alquilo a otras personas perjudicandome ya que no me devuelve mi dinero y me dejo sin hospedaje yo soy de Catamarca capital y viajo mañana', 'Tucuman 88 Tinogasta', 'LatLng(-27.947641, -67.56671)', 'xJpC047pWd3Hhg9', '', '', 'silmar7524@gmail.com', '', TRUE, '2025-05-22', '14:05:31', 'Demorado', '7', 19, '2025-10-14', '*NINGUNO*', 'gL3S8g9PYhjfJar7UD', '1263-DEN-576364', '--', NULL, 'Aún sin valoración', 'Aún sin comentarios', 283, 4),
